<template><section class="space-y-6"><h1 class="text-2xl font-semibold">Roles</h1><div class="grid gap-4 md:grid-cols-2"><article v-for="role in roles" :key="role.id" class="rounded-xl bg-background p-5 shadow"><h2 class="font-semibold">{{ role.name }}</h2><p class="mt-2 text-sm text-muted-foreground">{{ role.permissions.join(', ') || 'No permissions' }}</p></article></div></section></template>
<script setup lang="ts">import { onMounted, ref } from "vue"; import { authHttp } from "@/auth"; const roles = ref<any[]>([]); onMounted(async () => { const { data } = await authHttp.get("/api/staff/roles"); roles.value = Array.isArray(data) ? data : data.roles || []; });</script>
